function(container, apiUrl, tables) {
  const loginForm = container.querySelector('#login-form');
  const usernameInput = container.querySelector('#username');
  const passwordInput = container.querySelector('#password');
  const togglePasswordBtn = container.querySelector('#toggle-password');
  const rememberMeCheckbox = container.querySelector('#remember-me');
  const errorMessage = container.querySelector('#error-message');
  const forgotPasswordLink = container.querySelector('#forgot-password');

  // パスワード表示/非表示切り替え
  togglePasswordBtn.addEventListener('click', () => {
    const isPassword = passwordInput.type === 'password';
    passwordInput.type = isPassword ? 'text' : 'password';
    togglePasswordBtn.textContent = isPassword ? '非表示' : '表示';
  });

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove('hidden');
  }

  function hideError() {
    errorMessage.classList.add('hidden');
  }

  // ログイン処理
  async function handleLogin(username, password, rememberMe) {
    try {
      // ユーザーテーブル（tables[0]）からユーザー情報を取得
      const users = await window.aivicApi.list(0);
      if (!users) {
        showError('システムエラーが発生しました。管理者にお問い合わせください。');
        return false;
      }

      // ユーザー名とパスワードの照合（実際の実装ではハッシュ化されたパスワードと照合）
      const user = users.find(u => 
        u.ユーザー名 === username && 
        u.有効フラグ === true
      );

      if (!user) {
        showError('ユーザー名またはパスワードが正しくありません。');
        return false;
      }

      // 簡易的なパスワード照合（実際の実装ではハッシュ化されたパスワードと照合）
      // ここではデモ用に平文で比較
      if (user.パスワードハッシュ !== password) {
        showError('ユーザー名またはパスワードが正しくありません。');
        return false;
      }

      // 最終ログイン日時を更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // ログイン状態を保持する場合はlocalStorageに保存
      if (rememberMe) {
        localStorage.setItem('worklog_user_id', user.ユーザーID);
        localStorage.setItem('worklog_username', user.ユーザー名);
      }

      // セッションストレージにユーザー情報を保存
      sessionStorage.setItem('current_user', JSON.stringify({
        ユーザーID: user.ユーザーID,
        ユーザー名: user.ユーザー名,
        氏名: user.氏名,
        所属部署: user.所属部署,
        職種: user.職種,
        権限レベル: user.権限レベル
      }));

      return true;
    } catch (error) {
      console.error('Login error:', error);
      showError('ログイン処理中にエラーが発生しました。');
      return false;
    }
  }

  // フォーム送信処理
  loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    hideError();

    const username = usernameInput.value.trim();
    const password = passwordInput.value;
    const rememberMe = rememberMeCheckbox.checked;

    if (!username || !password) {
      showError('ユーザー名とパスワードを入力してください。');
      return;
    }

    // ログインボタンを無効化
    const loginBtn = container.querySelector('#btn-login');
    loginBtn.disabled = true;
    loginBtn.textContent = 'ログイン中...';

    try {
      const success = await handleLogin(username, password, rememberMe);

      if (success) {
        // ログイン成功時はメイン画面に遷移
        if (typeof window.onLoginSuccess === 'function') {
          window.onLoginSuccess();
        } else {
          // フォールバック: 工数記録画面に直接遷移
          window.showScreen("scr-1778907133295");
        }
      }
    } finally {
      // ログインボタンを有効化
      loginBtn.disabled = false;
      loginBtn.textContent = 'ログイン';
    }
  });

  // パスワードを忘れた場合のリンク
  forgotPasswordLink.addEventListener('click', (e) => {
    e.preventDefault();
    alert('パスワードリセット機能は管理者にお問い合わせください。');
  });

  // ページ読み込み時に保存されたログイン情報があれば復元
  const savedUserId = localStorage.getItem('worklog_user_id');
  const savedUsername = localStorage.getItem('worklog_username');

  if (savedUserId && savedUsername) {
    usernameInput.value = savedUsername;
    rememberMeCheckbox.checked = true;
    passwordInput.focus();
  } else {
    usernameInput.focus();
  }

  // Enterキーでのフォーム送信を有効化
  usernameInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      passwordInput.focus();
    }
  });

  passwordInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      loginForm.dispatchEvent(new Event('submit'));
    }
  });
}
